thermal=r'热成风是两层地转风之差，等价地可用地转风垂直切变描述。在静力、理想干气体及局地 $f\ne0$ 的条件下，由 $\vec V_g=f^{-1}\vec k\times\nabla_p\Phi$ 与 $\frac{\partial\Phi}{\partial p}=-RT/p$ 得 $\frac{\partial\vec V_g}{\partial p}=-\frac{R}{fp}\vec k\times\nabla_p T$。注意气压向上减小：北半球“上层减下层”的热成风背风而立，暖空气在右；该方向不能直接套到正气压方向的导数。'
upstream=r'按本资料用语，上游扰动的影响可借波包频散先传到下游，使下游在上游槽脊移到当地之前发生变化。须满足相应分支群速对地向下游、且传播快于槽脊等条件；不表示下游在上游扰动产生之前变化，也不保证任一阻高建立都使某一下游槽必然加深。'
pv=r'单层浅水流体在无摩擦、无质量源且层厚 $h>0$ 时，有 $\frac{D}{Dt}\left(\frac{\zeta+f}{h}\right)=0$。在完整干大气中，对应的 Ertel 位涡是 $q=\rho^{-1}\boldsymbol\omega_a\cdot\nabla\theta$，在绝热、无摩擦条件下随质点守恒；两种模型的位涡定义不能混用。'
mountain=r'设浅水层的上界近似水平、下界为山地，来流向东且原绝对涡度为正。迎风坡使层厚 $h$ 减小，守恒的 $(\zeta+f)/h$ 要求绝对涡度减小；背风坡 $h$ 增大则要求绝对涡度增大。这个结论描述沿路径的增减，不自动保证背风坡已出现正的相对涡度。'+'\n\n'+r'尤其在固定 $f$、初始 $\zeta=0$ 的理想模型中，若返回原层厚，$\zeta$ 也回到零。若迎风反气旋偏转使北半球气块向南移动，返回原层厚时 $f$ 较小，便可由 $\zeta=f_{\rm in}-f>0$ 产生气旋式弯曲；真实背风槽还涉及行星波响应、基本流、自由面/等熵面变形等。不能额外无依据地指定“背风必辐合”或将所有背风气旋归于单一过程。'

add(1,'一',1,'锋区','锋区是冷暖气团之间水平温度或密度梯度显著的有限过渡区，常伴湿度及风的明显变化；锋面是对这一过渡区作几何简化的界面。真实锋区有厚度，不能同时把密度本身说成不连续又说成连续；理想不连续面与实际梯度应分别讨论。','删除自相矛盾的“一级不连续”说明，保留实际有限厚度。')
add(1,'一',2,'热成风',thermal,'从静力关系核对气压坐标负号；区分向上风差与向下气压导数。')
add(1,'一',3,'阻塞高压','中高纬西风带中持续、移动缓慢的高压脊或反气旋，使正常西风通道偏转、分支，阻碍天气系统东移。阻塞可组织冷空气积聚和输送，但其建立或崩溃与寒潮并非一一对应，需结合槽、高压、冷空气储备和路径分析。','删除建立必积冷、崩溃必寒潮的绝对因果。')
add(1,'一',4,'CISK机制','第二类条件不稳定描述积云潜热加热与较大尺度低层辐合之间的正反馈：辐合供给水汽并组织对流，加热及相应环流调整可增强低层辐合。它是解释热带扰动发展的历史理论之一，需要相应闭合假设；台风维持还必须考虑海气焓通量、辐射和摩擦耗散，不能把 CISK 作为唯一机制。','区分加热反馈与海洋能量供给，不声称唯一核心。')
add(1,'一',5,'罗斯贝波',r'罗斯贝波以背景位涡梯度为回复机制。均匀基本流、正压无辐散 $\beta$ 平面模型中 $\omega=kU-\frac{\beta k}{k^2+l^2}$，纬向相速 $c_x=U-\frac{\beta}{k^2+l^2}$。只有 $l=0$ 时，才可写成 $c_x=U-\beta L_x^2/(4\pi^2)$。相对基本流向西；对地东移、静止或西移取决于尺度和 $U$。','限定模型与二维/一维波长区别，避免把所有罗斯贝波限定西风带。')
add(1,'一',6,'埃克曼抽吸',r'边界层摩擦改变水平输送，其辐合/辐散通过连续方程在边界层顶产生垂直运动，称埃克曼抽吸/泵吸。在不可压或Boussinesq近似、平坦不透水下界 $w=0$ 下，有 $w(h)=-\int_0^h\nabla_h\cdot\vec V\,dz$。可压大气应改用含密度的质量连续方程并计入质量储存。典型低压摩擦辐合对应上升；但水平均匀的单柱埃克曼螺线本身不自动产生抽吸。摩擦对气旋的衰减须结合自由大气与边界层的整体涡度、能量收支，不能解释为把涡度直接“抽走”。','用连续积分解释抽吸，排除单柱自动抽吸与涡度搬运误解。')
add(1,'一',7,'有效位能',r"有效位能是给定绝热重排约束下实际态总位能相对最低能量参考态的可用部分；干大气总位能包含内能与重力位能。稳定 Boussinesq 基本态的小扰动可写单位质量有效位能 $a=\frac{b'^2}{2N^2}$，其中 $b'=g\theta'/\theta_0$、$N^2=\frac{g}{\theta_0}\frac{d\theta_0}{dz}>0$，总量 $A=\int a\,dm$。$a$ 的量纲为 $\mathrm{m^2\,s^{-2}}$。该式是局地二次近似，不能当作任意大振幅大气的精确 Lorenz 定义；原式 $\int T'^2/\overline T\,dm$ 缺能量量纲因子。",'更正量纲错误，明确参考态约束及小扰动适用域。')
add(1,'一',8,'准地转运动',r'准地转运动是地转平衡占主导、较小非地转运动负责缓慢演变的旋转分层流动。中纬度尺度上常有 $Ro=U/(|f|L)\ll1$，并结合适当时间尺度、静力与稳定层结等近似建立准地转理论。单有小罗斯贝数不保证任何边界层或强非绝热过程都符合完整准地转假设。','小罗斯贝数是重要尺度条件，不等于全部理论假设。')
add(1,'一',9,'梅雨锋','梅雨锋是东亚初夏梅雨—白雨雨带相关的准静止锋区，江淮等某些区段水汽、相当位温梯度和低层切变突出，温度梯度相对较弱；其性质有明显区域差异，不能说整个东亚锋区均无温差。稳定水汽输送、扰动和上升共同维持持续或反复降水。','限定温差弱的区域性，不将持续降雨当作每时每地必下雨。')
add(1,'一',10,'上游效应',upstream,'更正时间因果并补充群速传播条件。')
add(1,'二',1,'东亚季风形成因子','海陆热力差异及其季节变化提供重要背景；行星环流和副热带高压的季节调整影响风向、水汽路径；青藏高原的机械阻挡与季节热源改变环流。海温和海气耦合、越赤道气流及对流加热进一步调节季风。索马里急流是跨赤道气流的一支，主要连接印度洋—南亚，不能把东亚水汽来源简化成仅由它直接输送。','补充多支水汽通道与海气作用，修正索马里急流的单一归因。')
add(1,'二',2,'温带气旋生命史','以挪威锋面气旋概念模型为例：初生波动使锋面弯曲并出现低压；开放波发展阶段冷暖锋清楚、暖区存在，低压可加深；锢囚阶段冷锋追及暖锋，暖空气被抬离地面；衰减阶段能量转换和有利高空配合减弱，气旋填塞。强度峰值不必恰在锢囚时，锢囚后仍可加深；暖心变冷心不是普遍消亡标准，其他生命史模型也存在。','删除固定峰值和暖心转冷心的错误普遍化。')
add(1,'二',3,'高空西风急流',r'急流是对流层上部或对流层顶附近的狭长强风带，极锋急流和副热带急流的纬度、高度、季节变化不同，不能固定在同一气压面或风速。北半球若南暖北冷，由 $\frac{\partial u_g}{\partial p}=\frac{R}{fp}\frac{\partial T}{\partial y}<0$ 可知向上西风增强。急流北侧常有气旋式、南侧常有反气旋式水平切变；曲率也影响总涡度。热成风解释垂直结构，涡旋动量输送及角动量约束等参与急流维持。','热成风符号与切变涡度核对，删固定高度风速及单因成因。')
add(1,'二',4,'寒潮源地与路径','本地资料常概括新地岛以西、新地岛以东及冰岛以南洋面等源区；冷空气在欧亚大陆积聚、改性后进入关键区再南下。西北路（中路）经蒙古高原—河套南下；西路偏经新疆、青海及高原东侧；东路主力东移并可有低层回流南下。课件称通常最强的寒潮来自西北路，但不能把通常强度、频次、受灾范围三个统计量都判作同一路径必居首位。','保留课件路径，删无统计依据的三项“最高”。')
add(1,'二',5,'地转偏差',r'地转偏差 $\vec V_a=\vec V-\vec V_g$。局地水平动量方程写成 $D\vec V/Dt+f\vec k\times\vec V_a=\vec F$，于是 $\vec V_a=f^{-1}\vec k\times(D\vec V/Dt-\vec F)$；无摩擦时由加速度决定。其散度通过质量连续与垂直运动、气压变化联系，穿越等高线可改变质量分布。变压风是特定近似下的一个分量；不能把非地转运动笼统说成所有系统发生消亡的唯一直接原因。','补完整动力表达式、摩擦项及质量连续的联系。')
add(1,'二',6,'瑞利散射与蓝天',r'分子尺度远小于可见光波长时，瑞利散射截面近似随 $\lambda^{-4}$ 变化，较短波长更易被散射进入侧向视线。太阳光谱、视网膜响应和大气传输共同使天空通常呈蓝色，而不是散射更强的紫色。红光也会散射，只是较弱；近地平线长光程时直射束中短波损耗较大，可呈红色。','补蓝紫区别，修正红光几乎完全直达的夸大。')
add(1,'三',1,'梅雨环流与锋区结构','高层结合南亚高压、急流和有利辐散配置；中层结合中高纬阻塞与槽及西太副高北缘；低层看江淮切变线、低空西南急流、水汽辐合及地面梅雨锋。课件的典型双阻图为乌拉尔山与雅库茨克附近两阻，中间宽广低槽，其南侧可有较平直西风和短波东移；这是一种型，非所有梅雨的必备配置。\n\n副高脊线常约在20°—25°N附近时，其北侧输送暖湿空气有利江淮雨带，具体经度和年份会变化。梅雨锋部分区段温差较弱而湿度/相当位温梯度、低层切变明显，下部湿层深；锋坡和雨带位置不宜背成全年固定数值。高层反气旋本身也不保证梅雨区处处辐散。','按已查课件改雅库茨克双阻图，取消必备环流和固定坡度。')
add(1,'三',2,'台风发展与CISK','有利环境包括足够的海洋热含量、湿润的中低层、可组织的初始旋涡、较小环境垂直风切变及适宜的旋转背景。约26.5°C海温、离赤道若干纬度是经验指标，不能当作无例外硬阈值；条件具备也不保证生成。\n\n在 CISK 框架中，较大尺度辐合供水汽并组织对流，潜热加热与相应压力、环流调整反过来增强辐合，构成反馈。暖核、上层外流和近地面气压下降须通过静力、质量连续及动量调整共同说明，“加热必立即辐散”不是独立定律。\n\n海气显潜热通量持续供能，摩擦耗散、干空气侵入、切变和海面冷却可限制发展；不能由示意反馈断言强度无限指数增长。季风槽、东风波等提供初始扰动，分类可重叠。','经验条件、热源和环流反馈分开，删除唯一机制与无限指数增长。')
add(1,'三',3,'位涡与背风槽',pv+'\n\n'+mountain,'指出固定f恢复层厚的反例，补β位移及模型条件，不将涡度增大等同已为正。')
add(1,'四',1,'正压罗斯贝波推导',r'''取 $f=f_0+\beta y$、均匀基本流 $U$，小扰动 $u=U+u'$、$v=v'$。舍去扰动乘积，得
$$\left(\frac{\partial}{\partial t}+U\frac{\partial}{\partial x}\right)\zeta'+\beta v'=0.$$
由无辐散条件引入 $u'=-\frac{\partial\psi'}{\partial y}$、$v'=\frac{\partial\psi'}{\partial x}$，于是 $\zeta'=\nabla_h^2\psi'$。代入平面波 $\psi'=\Psi e^{i(kx+ly-\omega t)}$，有
$$i(\omega-kU)(k^2+l^2)\Psi+i\beta k\Psi=0.$$
非零振幅且 $k^2+l^2>0$ 给出
$$\boxed{\omega=kU-\frac{\beta k}{k^2+l^2}}.$$
纬向相速（$k\ne0$）与群速为
$$c_x=\frac{\omega}{k}=U-\frac{\beta}{k^2+l^2},\qquad c_{gx}=\frac{\partial\omega}{\partial k}=U+\frac{\beta(k^2-l^2)}{(k^2+l^2)^2},\qquad c_{gy}=\frac{\partial\omega}{\partial l}=\frac{2\beta kl}{(k^2+l^2)^2}.$$
只有 $l=0$ 时，$c_x=U-\beta L_x^2/(4\pi^2)$、$L_x=2\pi/|k|$。$\omega/k$ 表示沿纬向相位截点的速度，不是沿波矢方向的相速矢量模。群速可与相速不同，其对地传播方向须用具体波数和基本流判断。''','重算色散与两个群速偏导，修正二维相速误用一维波长。')

add(4,'一',1,'斜压大气',r'斜压指 $\nabla p\times\nabla\rho\ne0$，即等压面和等密度面不平行。理想干气体中表现为等压面上有水平温度梯度；湿空气需使用虚温。斜压态可提供不稳定发展的能量条件，但斜压并不自动意味着已满足某个模型的不稳定条件或气旋必然发展。','分清斜压定义、湿空气修正与不稳定判据。')
add(4,'一',2,'涡度',r'涡度是速度旋度 $\boldsymbol\omega=\nabla\times\vec V$；天气学常用其竖直分量 $\zeta=\frac{\partial v}{\partial x}-\frac{\partial u}{\partial y}$，以向上为正。正值对应水平逆时针旋转，在北半球为气旋式、南半球为反气旋式；流场既可由曲率也可由切变产生涡度。','补向上约定与南半球符号，避免将标量当全部旋度。')
add(4,'一',3,'热成风',thermal,'改气压坐标负号并给静力推导。')
add(4,'一',4,'切断低压','切断低压是高空槽发展后与主要西风气流分离的闭合低压/低涡，常具冷心并移动缓慢。东北冷涡可作为相关实例，但并非每次东北低涡都严格满足同一切断演变。冷涡有利不稳定和上升配合时可出现阴雨或强对流，实际天气取决于水汽及动力条件。','保留概念，取消东北个例与天气的绝对等同。')
add(4,'一',5,'低空急流','低空急流是低层风速随高度出现显著极大值的强风带。天气尺度急流常用850—700hPa等层分析，边界层急流可低得多；高度、风速和上下层风速差的判据随资料而变，不以12m/s概括全部类型。它可输送暖湿空气，只有相应水汽辐合、抬升与持续条件配合时才有利强降水。','移除统一风速高度阈值，区别输送与通量辐合。')
add(4,'一',6,'阳伞效应','阳伞效应通常指气溶胶对太阳短波的散射、反射及相关云效应减少地表获得的太阳能。应区分地表短波减弱、气溶胶层吸收加热和大气顶净效应；吸收性气溶胶可同时使地表变暗而加热大气，不能由“阳伞”断言所有气溶胶对整个系统均净降温。','区分地表和大气顶，补吸收性粒子的不同响应。')
add(4,'一',7,'理查森数',r'梯度理查森数 $Ri_g=\frac{N^2}{(\frac{\partial\bar u}{\partial z})^2+(\frac{\partial\bar v}{\partial z})^2}$，干空气中 $N^2=\frac{g}{\bar\theta}\frac{\partial\bar\theta}{\partial z}$。分母是矢量风的垂直切变平方，不能一般地用风速大小的导数平方替代。在平行、无黏、稳定分层等理想假设下，处处 $Ri_g>1/4$ 可保证对相应微小扰动稳定；某处小于1/4只是可能失稳的必要门槛，非必然湍流判据。','补风向切变、定义及四分之一判据适用条件。')
add(4,'一',8,'上游效应',upstream,'区分相位到达与扰动开始，补群速条件。')
add(4,'一',9,'相速度和群速度',r'一维单色波 $e^{i(kx-\omega t)}$ 的相速是 $c_p=\omega/k$（$k\ne0$）；窄带波包的群速为 $c_g=d\omega/dk$。多维时 $\vec c_g=\nabla_{\vec k}\omega$。在适当保守线性波条件下群速描述波能传播；有耗散、增长或强非均匀背景时须另查波能/波作用收支。频散表示相速随波数而变，不能仅靠某个孤立波数处两个速度偶然相等来判定整支波非频散。','明确维数与能量解释条件，避免以孤立相等判断非频散。')
add(4,'一',10,'赤道东风波','这里按教材常用的热带东风波理解：它是热带东风背景中的波状天气尺度扰动，常随背景向西移动，并可为热带气旋提供初始旋涡。对流相对槽轴的位置依环境切变、垂直结构、水汽和地区而变，不能把东侧永远坏天气、西侧永远晴天当成普遍性质。它也不能仅凭名称等同于某一赤道浅水自由波模态。','去除固定降水相位，区别天气扰动与赤道自由波。')
add(4,'二',1,'江淮气旋形成','典型过程包括江淮锋区/切变线附近已有低层扰动，冷暖空气交汇保持斜压性；高空槽、急流及随高度变化的涡度平流和温度平流配置有利上升与质量调整；西南急流供水汽与热量，凝结加热又可反馈发展。高原及下游地形可调节扰动和流场，但地形并非每次气旋的必要成因。仅有某一层正涡度平流，不能直接断言地面必减压。','补三维质量配置，避免单层平流或地形直接决定成生。')
add(4,'二',2,'地形对降水的增强','有足够水汽时，迎风强迫抬升使气块冷却凝结；山谷或地形通道的辐合可触发对流；地形阻挡和重复生成可延长局地降水持续时间；高低云叠置时还可有播撒—供给等微物理增强。并非有喇叭口、爬坡就必有暴雨，风向、层结、含水量和系统移动共同决定结果，背风区也可能减雨。','恢复水汽、层结和时间条件，补微物理路径。')
add(4,'二',3,'角动量输送与风带',r'单位质量绝对轴向角动量为 $M=a\cos\varphi(\Omega a\cos\varphi+u)$。统计稳态下，平均环流和涡旋输送的辐合/辐散与地表摩擦力矩、山脉力矩等共同平衡。地面东风区的大气通常从地面摩擦获得正角动量，西风区通常向地面损失角动量；内部输送在不同纬度间重新分配。\n\nHadley上支及中纬度涡旋动量输送有助于维持副热带/中纬度西风，须看通量的散度和边界力矩。不能把中纬度涡旋一概写成向赤道输送，也不能从地球转速近恒定直接推出某一固定输送链。'.replace(r'\n\n','\n\n'),'改角动量输送方向及稳态收支，补山脉力矩。')
add(4,'二',4,'位涡守恒及应用',pv+'\n\n'+mountain,'区分Ertel与浅水位涡，补地形应用反例及条件。')
add(4,'二',5,'冷空气源地、路径与季节','源区可按本地课程概括为新地岛以西、新地岛以东及冰岛以南洋面等；南下前还经历欧亚大陆蓄积和变性。路径常归为西路、西北路（中路）、东路，另有路径汇合。\n\n**待核部分：** 题目要求三类路径的季节差异，现有模拟原稿没有统计年份、路径判别口径及各季频数，不能确认“冬季必以西北路为主”等排序。物理上冷源强度、槽脊位置和引导气流随季节改变，但具体哪类在何季占优须用对应教材或统计补证；复习时不把本题的季节排序当成已核实结论。','源地和路径概念已核；季节频率排序缺依据，保留待核。')
add(4,'二',6,'中低纬度运动差异',r'中纬度天气尺度中 $|f|$ 较大，适当尺度下 $Ro=U/(|f|L)\ll1$，地转与静力平衡可作主要近似，斜压过程常重要。低纬度 $f$ 较小、赤道附近趋零，同样 $U,L$ 下惯性加速度和辐合运动较难忽略，需考虑赤道 $\beta$ 效应、海气交换与深对流加热。\n\n这是典型尺度比较，不能说低纬度处处正压或只有潜热供能，也不能说中纬度无深对流。静力近似主要由垂直尺度和加速度决定，不因纬度低就自动失效。'.replace(r'\n\n','\n\n'),'补全原稿空泛交叉指引，限定典型尺度与纬度解释。')
add(4,'三',1,'温带气旋与台风','典型温带锋面气旋结构不对称，有明显锋区和温度梯度，发展依赖基本态有效位能转换及高低层相位配合，潜热也可重要。典型成熟热带气旋为深厚暖心、较轴对称且无经典冷暖锋的低压，持续海气焓通量、对流加热、环流调整与耗散共同决定强度。\n\n温带气旋不能一概称全层冷心，可能有暖区或暖核锢囚；热带气旋也不是每个阶段都有清楚的眼。二者尺度范围可重叠，最大风位置和垂直伸展依个例而变。温带转化时热带气旋可获得锋面和斜压结构，因此表格中的典型差异不应写成无例外的分类门槛。','修正全冷心、必有眼、CISK唯一机制等硬分类。')
add(4,'三',2,'水汽通量及散度',r'''在气压坐标中，水平水汽通量常先写 $q\vec V$；取柱上界 $p_t$、地表 $p_s$，整层积分输送为
$$\vec Q=\frac1g\int_{p_t}^{p_s}q\vec V\,dp,\qquad W=\frac1g\int_{p_t}^{p_s}q\,dp.$$
$q$ 为比湿（$\mathrm{kg/kg}$），$\vec Q$ 的单位为 $\mathrm{kg\,m^{-1}\,s^{-1}}$，表示每单位水平长度的整层输送；$W$ 为单位面积柱水汽质量（$\mathrm{kg\,m^{-2}}$）。$D_q=\nabla_h\cdot\vec Q$ 的单位为 $\mathrm{kg\,m^{-2}\,s^{-1}}$，负值代表水平净汇入。

取整大气柱（或上界水汽通量可忽略），并忽略云凝结物储存和输送等修正时，柱收支写作 $\frac{\partial W}{\partial t}+\nabla_h\cdot\vec Q=E-P$。任意有限上界若有水汽交换，还须计入穿越该边界的净通量。因此辐合并不直接等于降水，还需考虑蒸发与柱储存变化。

用统一的比湿、风、气压层厚和地形掩膜作垂直积分，再按网格几何计算水平散度；地表气压随位置变化时不能随意交换积分和水平求导。''','补积分界限、单位、柱储存和地形边界，避免辐合等于雨量。')
add(4,'三',3,'阻塞高压演变与天气','建立时可有行星波脊放大、波破碎及高低频扰动相互作用，使西风分支或通道偏离；维持依赖持续的涡旋通量反馈及大尺度背景，暖平流可参与但不是唯一机制。偶极阻塞和Ω型等形态不同，南侧切断低压不是所有阻塞的必要组成。\n\n上游扰动、急流和涡旋反馈变化可使阻塞削弱、移动或重组。其对我国天气的影响取决于位置、季节与配合系统：可引导冷空气、造成持续雨带或使部分地区晴热少雨。应追踪冷高压与槽的演变，不能把“崩溃”单独当作寒潮必然爆发信号。','按波—流和涡旋反馈解释生命史，删除单一暖平流与必寒潮链。')
add(4,'四',1,'重力惯性外波推导',r'''题给方程已是静止、均匀厚度 $H>0$、常 $f_0$ 背景上的线性方程。把其中扰动厚度记作 $\eta$，总层厚为 $H+\eta$，避免重复线性化时混淆 $h$ 的意义。取 $\frac{\partial}{\partial y}=0$ 及平面波 $(u,v,\eta)=(U,V,Z)e^{i(kx-\omega t)}$，得到
$$\begin{pmatrix}-i\omega&-f_0&igk\\f_0&-i\omega&0\\iHk&0&-i\omega\end{pmatrix}\begin{pmatrix}U\\V\\Z\end{pmatrix}=0.$$
行列式给完整频率关系
$$\boxed{\omega(\omega^2-f_0^2-gHk^2)=0}.$$
零频分支是平衡模态；当 $f_0\ne0$、$k\ne0$ 时 $U=0$、$f_0 V=igkZ$。在消元除以 $\omega$ 前必须把它单列。

两个传播分支为 $\omega_s=s\sqrt{f_0^2+gHk^2}$，$s=\pm1$。对任意非零 $k$，
$$c_{p,s}=\frac{\omega_s}{k},\qquad c_{g,s}=\frac{d\omega_s}{dk}=\frac{gHk}{\omega_s}=s\frac{gHk}{\sqrt{f_0^2+gHk^2}}.$$
这种写法同时保留频率分支和波数符号；不能先写正根群速再无条件接上正负号。当 $f_0\ne0$、$k\to0$ 时 $|\omega|\to|f_0|$、$c_g\to0$，$|c_p|$ 发散，但 $k=0$ 无有限波长可定义相速，发散不表示能量无限快传播。$|k|\to\infty$ 时 $|c_p|,|c_g|\to\sqrt{gH}$。''','重算行列式保留零频分支，修群速分支和负波数符号，补长波物理极限。')

assert all(len(v)==20 for v in entries.values())
records=['# 模拟一、四逐题复核记录','','2026-11-04。新增复核范围为模拟一、四的40个唯一小题；模拟一同时用于D40/D41，模拟四用于D46。它们独立于536条年度真题记录，不重复计入该总数。39题完成本轮内容核对，模拟四二5的源地/路径已核但季节频率排序仍待核。原模拟资料保留原文，日课采用修订版。','','| 题目及原稿位置 | 状态 | 核对内容 |','|---|---|---|']
for vol,days in [(1,[40,41]),(4,[46])]:
    word={1:'一',4:'四'}[vol]
    orig=root.parent/'模拟试题'/f'模拟试题{word}.md'
    lines=orig.read_text(encoding='utf-8').splitlines();section=None;active=False;loc={}
    for i,line in enumerate(lines,1):
        if f'# 模拟试题{word} · 参考答案' in line: active=True
        if not active: continue
        if m:=re.match(r'## ([一二三四])、',line):
            section=m[1]
            if section=='四':loc[(section,1)]=i
        if m:=re.match(r'\*\*(\d+)\.',line):loc[(section,int(m[1]))]=i
    header=f'# 模拟试题{word} · 参考答案'
    chunks=[header,'','**2026-11-04 逐题修订版。** 原稿存在符号、量纲和适用条件问题，以下按本题条件作答。[逐题记录]('+base+quote('50日任务/复核依据/模拟一四复核记录.md')+')。','']
    current=None
    for sec,num,title,ans,note in entries[vol]:
        if sec!=current:
            chunks+=['## '+sec+'、'+{'一':'名词解释','二':'简答题','三':'论述题','四':'推导题'}[sec],''];current=sec
        source=base+quote('模拟试题/'+orig.name)+f'#L{loc[(sec,num)]}'
        chunks += [f'**{num}. {title}**','',ans,'',f'[原模拟资料位置]({source})','']
        status='内容复核；季节频率待核' if (vol,sec,num)==(4,'二',5) else '内容复核'
        records.append(f'| [模拟{word}-{sec}-{num}]({source}) | {status} | {note} |')
    for day in days:
        p=root/'每日内容'/f'D{day:02}.md';s=p.read_text(encoding='utf-8')
        a=s.index(header);b=s.index('## 当日验收',a)
        s=s[:a]+'\n'.join(chunks)+'\n'+s[b:]
        s=s.replace('> 基于1989-2026年37年真题风格和命题规律编制，题型和难度完全仿真。','> 学习整理模拟题，用于练习与复盘；题型、难度和分值不代表官方命题。')
        p.write_text(s,encoding='utf-8')
records += ['', '## 复核依据与方法', '', '动力学公式以题给模型独立推导并核对量纲：热成风由地转与静力关系交叉微分；有效位能用稳定基本态的小扰动回复功；罗斯贝波与重力惯性波分别计算色散关系和群速。位涡过山题用固定f、恢复层厚的反例检查结论，避免把沿途增量误作绝对符号。', '', '天气学同时对照本地课件复核摘记：[梅雨与寒潮课件依据](天气课件复核.md)。路径季节频率缺统计资料的部分保留待核。', '', '热带气旋有利条件补充核对：[NOAA，Tropical Cyclone Introduction](https://www.noaa.gov/jetstream/tropical/tropical-cyclone-introduction)；阻塞形态与持续天气核对：[Met Office，Blocking patterns](https://weather.metoffice.gov.uk/learn-about/weather/how-weather-works/high-and-low-pressure/blocks)。', '', '本记录区分整理题的物理纠错与原卷评分审定；来源行链接指向被复核原稿，不表示原稿中的错误仍可直接采用。']
(root/'复核依据').mkdir(exist_ok=True)
(root/'复核依据/模拟一四复核记录.md').write_text('\n'.join(records)+'\n',encoding='utf-8')
print('Reviewed 40 unique mock questions; updated D40 D41 D46; 1 seasonal subquestion remains uncertain.')
